#include <Arduino.h>
#include <Servo.h>
Servo servo1;
Servo servo2;
const int LED1_PIN = 2;  
const int LED2_PIN = 3;  
const int SHCP_PIN = A2; 
const int STCP_PIN = A1; 
const int DS_PIN = A0;   
const int SERVO1_PIN = 4; 
const int SERVO2_PIN = 5; 
const byte segmentCodes[] = {
  0b11000000, 
  0b11111001, 
  0b10100100, 
  0b10110000, 
  0b10011001, 
  0b10010010, 
  0b10000010, 
  0b11111000, 
  0b10000000, 
  0b10010000  
};
int currentNumber = 0;
unsigned long previousMillisLED = 0;
unsigned long previousMillisDisplay = 0;
unsigned long previousMillisServo = 0;
bool isServoPaused = false;
unsigned long pauseStartTime = 0;
bool led1State = LOW;
bool led2State = HIGH;

void setup();
void loop();
void displayNumber(int number);
void setup() {
  pinMode(LED1_PIN, OUTPUT);
  pinMode(LED2_PIN, OUTPUT);
  pinMode(SHCP_PIN, OUTPUT);
  pinMode(STCP_PIN, OUTPUT);
  pinMode(DS_PIN, OUTPUT);
  servo1.attach(SERVO1_PIN);
  servo2.attach(SERVO2_PIN);
  digitalWrite(LED1_PIN, led1State);
  digitalWrite(LED2_PIN, led2State);
  displayNumber(currentNumber);
}
void loop() {
  unsigned long currentMillis = millis();
  if (currentMillis - previousMillisLED >= 2000) {
    previousMillisLED = currentMillis;
    led1State = !led1State;
    led2State = !led2State;
    digitalWrite(LED1_PIN, led1State);
    digitalWrite(LED2_PIN, led2State);
  }
  if (currentMillis - previousMillisDisplay >= 2000) {
    previousMillisDisplay = currentMillis;
    currentNumber = (currentNumber + 1) % 10;
    displayNumber(currentNumber);
  }
  if (!isServoPaused) {
    if (currentMillis - previousMillisServo >= 20) {
      previousMillisServo = currentMillis;
      static int pos1 = 0;
      static int pos2 = 180;
      static int dir1 = 1;
      static int dir2 = -1;
      pos1 += dir1;
      pos2 += dir2;
      if (pos1 >= 180 || pos1 <= 0) dir1 = -dir1;
      if (pos2 >= 180 || pos2 <= 0) {
        dir2 = -dir2;
        isServoPaused = true;
        pauseStartTime = currentMillis;
      }
      servo1.write(pos1);
      servo2.write(pos2);
    }
  }
  else if (currentMillis - pauseStartTime >= 2000) {
    isServoPaused = false;
  }
}
void displayNumber(int number) {
  byte code = segmentCodes[number];
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, code);
  digitalWrite(STCP_PIN, HIGH);
  digitalWrite(STCP_PIN, LOW);
}
